// @hand-authored - hand-crafted story; not regenerated by gen-stories.
// Rebuilds @cc/react-components' HighlightCard `Default` + `SectionVariants` examples
// (Common-JS/react-components/src/stories/HightlightCard.stories.tsx) on the kernel's
// composed HighlightCard - see CARD-STRUCTURE-PLAN.md §2 and CARECONNECT-CARD-MAPPING.md.
import {
  HighlightCard, IconButton, IconPill, StatusPill, Chip, FieldList, Icon,
} from '@corilus/kernel';

export default {
  title: 'Core/Data Display/HighlightCard',
  component: HighlightCard,
  tags: ['autodocs'],
  argTypes: {
    tone: { control: 'select', options: ['neutral', 'primary', 'info', 'success', 'warning', 'error', 'data-1', 'data-2', 'data-3'], description: 'Colour identity of the shell, forwarded to the shell Card\'s own `tone`.', table: { category: 'Appearance' } },
    bordered: { control: 'boolean', description: 'The shell\'s hairline border.', table: { category: 'Appearance' } },
    title: { control: 'text', table: { category: 'Header' } },
  },
  parameters: {
    docs: {
      description: {
        component: [
          'A tagged header row over a stack of independently toned, optionally collapsible section-Cards. Composes `Card` + `Stack` - not a new primitive; each section is itself a `Card` (`tone` / `surface="tinted"` / `detail`), so the whole component is Card all the way down.',
          '',
          '**Import**',
          '',
          '```ts',
          "import { HighlightCard } from '@corilus/kernel'",
          '```',
          '',
          '## Sections, not an accordion',
          '',
          'Each entry in `sections` is independently toned, independently highlighted, and independently collapsible - there is no shared "one open at a time" coordination, unlike an Accordion. A section becomes collapsible by setting `collapsible: true`; its header is then a real Base UI trigger button (Change A gives it the right-aligned, down/up chevron for free), so its `actions` render inside the revealed panel rather than the header - putting a button inside the trigger would be a button-in-button.',
        ].join('\n'),
      },
    },
  },
};

const documentIcon = () => Icon.doc({ size: 18 });
const parametersIcon = () => Icon.gear({ size: 18 });
const otherIcon = () => Icon.doc({ size: 18 });

