// The @cc "SectionBorderBottom" example - a tone-coloured rule under the section
// header instead of Card's usual top strip (a small, honest new CSS rule; see
// CARECONNECT-CARD-MAPPING.md §3, "borderBottom ~ accent, a bottom rule is a small
// CSS add").
export const SectionBorderBottom = {
  parameters: {
    controls: { disable: true },
    docs: { description: { story: 'Sections can draw a bottom rule in their own tone via `borderBottom`.' } },
  },
  render: () => (
    <div style={{ maxWidth: 480 }}>
      <HighlightCard
        tone="primary"
        leading={<IconPill label="Consult">{Icon.user({ size: 18 })}</IconPill>}
        title="Sections with bottom rules"
        action={<IconButton aria-label="Edit">{Icon.gear({ size: 16 })}</IconButton>}
        sections={[
          { icon: documentIcon(), title: 'Success Section', tone: 'success', borderBottom: true, content: <FieldList items={[{ label: 'Feature', value: 'Bottom rule in the success tone.' }]} /> },
          { icon: documentIcon(), title: 'Warning Section', tone: 'warning', borderBottom: true, highlight: true, content: <FieldList items={[{ label: 'Type', value: 'Highlighted, with a bottom rule.' }]} /> },
          { icon: documentIcon(), title: 'Danger Section', tone: 'error', borderBottom: true, content: <FieldList items={[{ label: 'Alert', value: 'Bottom rule in the danger (error) tone.' }]} /> },
        ]}
      />
    </div>
  ),
};

