// Section-level actions: static (header, left) vs collapsible (relocated into
// `detail` - never the trigger button, avoiding a button-in-button).
export const SectionActions = {
  parameters: {
    controls: { disable: true },
    docs: { description: { story: 'A static section renders `actions` in its header; a collapsible section renders them inside `detail` instead - its header is a real trigger button, so a control can never nest inside it.' } },
  },
  render: () => (
    <div style={{ maxWidth: 480 }}>
      <HighlightCard
        leading={<IconPill label="Consult">{Icon.user({ size: 18 })}</IconPill>}
        title="Section actions"
        sections={[
          {
            icon: documentIcon(), title: 'Static section',
            actions: <StatusPill status="normal" label="Reviewed" />,
            content: 'A static section can safely put actions in its own header.',
          },
          {
            icon: parametersIcon(), title: 'Collapsible section', collapsible: true, highlight: true,
            actions: <StatusPill status="borderline" label="Pending" />,
            content: 'A collapsible section moves actions into the revealed panel instead of the header.',
          },
        ]}
      />
    </div>
  ),
};
